    """Get annotation for a key from its comment.

    Args:
        data: Dictionary loaded with ruamel.yaml round-trip parser
        key: Key to check for annotations

    Returns:
        str or None: The annotation or None
    """
    if hasattr(data, 'ca') and hasattr(data.ca, 'items'):
        if key in data.ca.items:
            comment_tokens = data.ca.items[key]
            # comment_tokens is a list [pre_key, post_key, pre_value, post_value]
            # We want the post_value comment (index 2)
            if len(comment_tokens) > 2 and comment_tokens[2] is not None:
                return extract_annotation_from_comment(comment_tokens[2])
    return None
